528	func getRepoSanitizerRegex(rootDir string) *regexp.Regexp {
529		// This regex assumes that the sensitive part of the path (the component immediately after "rootDir") contains no
530		// spaces. This assumption allows us to avoid sanitizing "more info" in "/tmp/_argocd-repo/SENSITIVE more info".
531		//
532		// The no-spaces assumption holds for our actual use case, which is "/tmp/_argocd-repo/{random UUID}". The UUID will
533		// only ever contain digits and hyphens.
534		return regexp.MustCompile(regexp.QuoteMeta(rootDir) + `/[^ /]*`)
535	}
