// checkoutReferencedHelmSources resolves and checks out any of the query's RefSources that are actually referenced by
// the given Helm value files (using the $refname/path/to/file.yaml syntax). Only referenced repositories are checked
// out - ref sources declared in RefSources but never referenced by a value file are ignored. Referenced ref source
// names are processed in lexicographically sorted order so that conflict error messages are deterministic.
func (s *Service) checkoutReferencedHelmSources(valueFiles []string, sha string, targetRevision string, q *apiclient.RepoServerAppDetailsQuery, tempPaths utilio.TempPaths) error {
	referencedSources := getReferencedSources(valueFiles, q.RefSources)
	if len(referencedSources) == 0 {
		return nil
	}

	refNames := make([]string, 0, len(referencedSources))
	for refName := range referencedSources {
		refNames = append(refNames, refName)
	}
	sort.Strings(refNames)

	// mainRepoURL is only set for git application repos, since revision conflicts are only meaningful between git
	// repositories.
	mainRepoURL := ""
	if q.Repo.Type == "git" {
		mainRepoURL = git.NormalizeGitURL(q.Repo.Repo)
	}

	repoRefs := make(map[string]repoRef)
	for _, refName := range refNames {
		refSource := referencedSources[refName]

		// Non-git referenced repositories (e.g. OCI) are expected to have been extracted already; we only look up
		// their cached path rather than performing any git operations.
		if refSource.Repo.Type != "git" {
			tempPaths.GetPathIfExists(git.NormalizeGitURL(refSource.Repo.Repo))
			continue
		}

		gitClient, refSHA, err := s.newClientResolveRevision(&refSource.Repo, refSource.TargetRevision, git.WithCache(s.cache, !q.NoRevisionCache && !q.NoCache))
		if err != nil {
			return fmt.Errorf("error setting up git client for %s and resolving revision %s: %w", refSource.Repo.Repo, refSource.TargetRevision, err)
		}

		refNormalizedURL := git.NormalizeGitURL(refSource.Repo.Repo)

		if mainRepoURL == refNormalizedURL && refSHA != sha {
			return fmt.Errorf("cannot reference a different revision of the same repository (%s references %q which resolves to %q while the application references %q which resolves to %q)", refName, refSource.TargetRevision, refSHA, targetRevision, sha)
		}

		if existing, ok := repoRefs[refNormalizedURL]; ok {
			if existing.commitSHA != refSHA {
				return fmt.Errorf("cannot reference multiple revisions for the same repository (%s references %q which resolves to %q while %s references %q which resolves to %q)", refName, refSource.TargetRevision, refSHA, existing.key, existing.revision, existing.commitSHA)
			}
			continue
		}

		closer, err := s.repoLock.Lock(gitClient.Root(), refSHA, true, func(clean bool) (goio.Closer, error) {
			return s.checkoutRevision(gitClient, refSHA, s.initConstants.SubmoduleEnabled, refSource.Repo.Depth, clean)
		})
		if err != nil {
			return fmt.Errorf("failed to acquire lock for referenced repo %q: %w", refSource.Repo.Repo, err)
		}
		defer utilio.Close(closer)

		repoRefs[refNormalizedURL] = repoRef{
			revision:  refSource.TargetRevision,
			commitSHA: refSHA,
			key:       refName,
		}
	}

	return nil
}

// getReferencedSources returns the subset of refSources that are actually referenced by the given value files using
// the $refname/path/to/file.yaml syntax, keyed by ref name.
func getReferencedSources(valueFiles []string, refSources map[string]*v1alpha1.RefTarget) map[string]*v1alpha1.RefTarget {
	referenced := make(map[string]*v1alpha1.RefTarget)
	for _, valueFile := range valueFiles {
		if !strings.HasPrefix(valueFile, "$") {
			continue
		}
		refVar := strings.Split(valueFile, "/")[0]
		if refSource, ok := refSources[refVar]; ok {
			referenced[refVar] = refSource
		}
	}
	return referenced
}

